UPDATE wp_buDIJ_posts SET post_excerpt='<b data-path-to-node="4" data-index-in-node="0">Retatrutide</b> es el pináculo de la evolución en péptidos metabólicos. Diseñado como un potente <b data-path-to-node="4" data-index-in-node="98">triple agonista</b> (GIP, GLP-1 y Glucagón), este compuesto va un paso más allá en la recomposición corporal al elevar activamente el ritmo metabólico, incluso en periodos de inactividad.' WHERE ID=15229;